open("axisymmetric_coil.fem")
mi_analyze(1)
mi_loadsolution()
current, voltage, flux = mo_getcircuitproperties("coil")
summary = openfile("axisymmetric_coil.summary.txt", "w")
write(summary, "circuit_current_A=", current, "\n")
write(summary, "voltage_drop_V=", voltage, "\n")
write(summary, "flux_linkage_Wb=", flux, "\n")
closefile(summary)
mo_close()
mi_close()
quit()
